return ['project-id-version'=>'StyleSwitch 1.0.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/style-switch','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-11-21T18:17:37+00:00','po-revision-date'=>'2026-11-21 18:19+0000','last-translator'=>'ic','language-team'=>'Czech','language'=>'cs_CZ','plural-forms'=>'nplurals=3; plural=(n==1) ? 0 : (n>=2 && n<=4) ? 1 : 2;','x-domain'=>'style-switch','messages'=>['A random string is appended. Letters, digits, "-" and "_".'=>'Připojí se k ní náhodný řetězec. Písmena, číslice, „-“ a „_“.','A widget that lets visitors switch the site between a light and a dark color scheme. Built on the StyleSwitch library: alternate style sheets, prefers-color-scheme and a cookie with the visitor\'s choice.'=>'Widget, kterým si návštěvníci přepnou web mezi světlým a tmavým barevným schématem. Postavený na knihovně StyleSwitch: alternativní styly, prefers-color-scheme a cookie s volbou návštěvníka.','Always follow it, even when the visitor has chosen a style ( the choice is deleted )'=>'Řídit se jím vždy, i když si návštěvník styl vybral (volba se smaže)','Apply the choice of the visitor already in the HTML of the page'=>'Použít volbu návštěvníka už v HTML stránky','Attribute title of the style sheet, shown in the widget ( and in Firefox in View → Page Style ).'=>'Atribut title stylu, zobrazí se ve widgetu (a ve Firefoxu v nabídce Zobrazit → Styl stránky).','Behavior'=>'Chování','By the operating system of the visitor'=>'Podle operačního systému návštěvníka','By the operating system: the dark style sheet gets media="(prefers-color-scheme: dark)" ( "preferred" style sheet ). Light or dark: the other style is only an "alternate" style sheet, used after the visitor chooses it.'=>'Podle operačního systému: tmavý styl dostane media="(prefers-color-scheme: dark)" (styl „preferred“). Světlý nebo tmavý: druhý styl je jen „alternate“ a použije se, až si ho návštěvník vybere.','CSS Naked Day'=>'CSS Naked Day','Caption of the drop-down list'=>'Popisek rozbalovacího seznamu','Caption of the form control'=>'Popisek ovládacího prvku','Caption of the radio buttons'=>'Popisek přepínacích tlačítek','Caption of the switch'=>'Popisek přepínače','Color scheme'=>'Barevné schéma','Cookie'=>'Cookie','Dark'=>'Tmavý','Day of the CSS Naked Day'=>'Den CSS Naked Day','Divider in the tooltip of the switch'=>'Oddělovač v bublinové nápovědě přepínače','Documentation of StyleSwitch'=>'Dokumentace StyleSwitch','Drop-down list'=>'Rozbalovací seznam','Drop-down list: element of the caption'=>'Rozbalovací seznam: element popisku','Drop-down list: roles'=>'Rozbalovací seznam: role','Empty fields use the default text shown in grey.'=>'Prázdná pole použijí výchozí text zobrazený šedě.','Fixed settings'=>'Pevná nastavení','Follow it only until the visitor chooses a style'=>'Řídit se jím, jen dokud si návštěvník nevybere styl','Form control:'=>'Ovládací prvek:','Group of the style without CSS in the drop-down list'=>'Skupina stylu bez CSS v rozbalovacím seznamu','Group of the styles in the drop-down list'=>'Skupina stylů v rozbalovacím seznamu','HTML which StyleSwitch builds in the widget.'=>'HTML, které StyleSwitch sestaví ve widgetu.','Joins the roles of the style sheets when they are shown as the tooltip ( see Markup ). Spaces are kept.'=>'Spojuje role stylů, když se zobrazují jako bublinová nápověda (viz HTML ovládacího prvku). Mezery se zachovají.','Keep the choice for ( days )'=>'Pamatovat si volbu (dní)','Label of the optgroup with the style without CSS. Empty: no group.'=>'Popisek skupiny (optgroup) se stylem bez CSS. Prázdné: bez skupiny.','Label of the optgroup with the styles. Empty: no group.'=>'Popisek skupiny (optgroup) se styly. Prázdné: bez skupiny.','Lets visitors switch the site between the light and the dark color scheme.'=>'Návštěvníci si přepnou web mezi světlým a tmavým barevným schématem.','Light'=>'Světlý','Load the built-in look of the switch'=>'Načíst vestavěný vzhled přepínače','Markup of the form control'=>'HTML ovládacího prvku','Month of the CSS Naked Day'=>'Měsíc CSS Naked Day','More settings: Settings → StyleSwitch'=>'Další nastavení: Nastavení → StyleSwitch','Name of the dark style'=>'Název tmavého stylu','Name of the light style'=>'Název světlého stylu','Name of the style without CSS'=>'Název stylu bez CSS','Needs the style without CSS turned on. The day is the date of the visitor.'=>'Vyžaduje zapnutý styl bez CSS. Rozhoduje datum u návštěvníka.','Never follow it in the widget'=>'Ve widgetu se jím neřídit nikdy','Offer the page without any CSS as one more style'=>'Nabízet stránku úplně bez CSS jako další styl','Offer the styles in reverse order'=>'Nabízet styly v opačném pořadí','Offers the page without any CSS ( naked HTML ) as one more style, for example for the CSS Naked Day. There are three styles then, so the widget shows a drop-down list instead of a switch.'=>'Nabídne stránku úplně bez CSS (čisté HTML) jako další styl, například pro CSS Naked Day. Styly jsou pak tři, a tak widget místo přepínače zobrazí rozbalovací seznam.','Only for the drop-down list, instead of the title of the widget.'=>'Jen pro rozbalovací seznam, místo názvu widgetu.','Only for the radio buttons, instead of the title of the widget.'=>'Jen pro přepínací tlačítka, místo názvu widgetu.','Only for the switch, instead of the title of the widget.'=>'Jen pro přepínač, místo názvu widgetu.','Only one StyleSwitch widget is shown on a page. Visitors without JavaScript or with a browser without the Cookie Store API do not see it.'=>'Na stránce se zobrazí jen jeden widget StyleSwitch. Návštěvníci bez JavaScriptu nebo s prohlížečem bez Cookie Store API ho neuvidí.','Order'=>'Pořadí','Part of the site the choice applies to, "/" is the whole domain.'=>'Část webu, pro kterou volba platí, „/“ je celá doména.','Partitioned'=>'Partitioned','Partitioned cookie ( CHIPS )'=>'Rozdělená cookie (partitioned, CHIPS)','Path'=>'Cesta','Prefix of the id'=>'Předpona id','Radio buttons'=>'Přepínací tlačítka (radio)','Radio buttons: element of the caption'=>'Přepínací tlačítka: element popisku','Radio buttons: roles'=>'Přepínací tlačítka: role','Role of the style sheet in the document ( persistent, preferred, alternate ) as a tooltip. Meant for developers.'=>'Role stylu v dokumentu (persistent, preferred, alternate) jako bublinová nápověda. Určeno pro vývojáře.','Roles of the style sheets as the tooltip'=>'Role stylů jako bublinová nápověda','Roles of the style sheets as tooltips of the items'=>'Role stylů jako bublinová nápověda tlačítek','Roles of the style sheets as tooltips of the options'=>'Role stylů jako bublinová nápověda položek seznamu','Server side'=>'Na serveru','Set in each widget.'=>'Nastavuje se v každém widgetu.','Setting'=>'Nastavení','Settings'=>'Nastavení','Settings of the StyleSwitch library for all StyleSwitch widgets. The title of the widget and the type of the form control ( switch, drop-down list, radio buttons ) are set in each widget.'=>'Nastavení knihovny StyleSwitch pro všechny widgety StyleSwitch. Název widgetu a typ ovládacího prvku (přepínač, rozbalovací seznam, přepínací tlačítka) se nastavují v každém widgetu.','Style before the visitor chooses'=>'Styl, dokud si návštěvník nevybere','Style without CSS'=>'Styl bez CSS','StyleSwitch'=>'StyleSwitch','StyleSwitch settings'=>'Nastavení StyleSwitch','StyleSwitch uses "switch" by default, the plugin uses its own class because themes often style "switch".'=>'StyleSwitch ve výchozím stavu používá „switch“, plugin vlastní třídu, protože šablony třídu „switch“ často stylují.','StyleSwitch – light / dark'=>'StyleSwitch – světlý / tmavý','Styles'=>'Styly','Switch (for two styles, otherwise a drop-down list)'=>'Přepínač (pro dva styly, jinak rozbalovací seznam)','Switch to the style without CSS automatically on the day below and back the next day'=>'V den níže automaticky přepnout na styl bez CSS a další den zpět','Switch: class of the label'=>'Přepínač: třída elementu label','Switch: class of the state'=>'Přepínač: třída stavu','Switch: class of the visual switch'=>'Přepínač: třída grafického přepínače','Switch: element of the caption'=>'Přepínač: element popisku','Switch: element of the state text'=>'Přepínač: element textu stavu','Switch: look'=>'Přepínač: vzhled','Switch: roles'=>'Přepínač: role','Text of the switch turned off'=>'Text vypnutého přepínače','Text of the switch turned on'=>'Text zapnutého přepínače','Texts'=>'Texty','The StyleSwitch widget is not in any widget area yet, nothing is shown on the site.'=>'Widget StyleSwitch zatím není v žádné oblasti widgetů, na webu se nic nezobrazí.','The active theme or another plugin adjusts the styles with the filter style_switch_styles, it can override the settings in this section.'=>'Aktivní šablona nebo jiný plugin upravuje styly filtrem style_switch_styles a může tak nastavení v této sekci přebít.','The choice of the visitor is stored in the cookie "%s" ( its name cannot be changed, see the fixed settings below ).'=>'Volba návštěvníka se ukládá do cookie „%s“ (její název změnit nejde, viz pevná nastavení níže).','The cookie listener ( live switching ) and the server side work with all style sheets of the page.'=>'Posluchač cookie (přepínání bez načtení stránky) i server pracují se všemi styly stránky.','The cookie listener, bundled without changes, has the name hard-coded.'=>'Posluchač cookie, přibalený beze změn, má název napevno.','The page is shown in the chosen style from the first moment. Turn it off when the HTML of the pages is cached for all visitors together ( full page cache ), the choice is then applied by JavaScript after the page loads.'=>'Stránka se zobrazí ve zvoleném stylu hned od začátku. Vypněte, pokud se HTML stránek ukládá do mezipaměti pro všechny návštěvníky společně (full page cache), volbu pak použije JavaScript po načtení stránky.','The style sheets the visitor switches between. The style sheets of the plugin only set the CSS property color-scheme of the page, the colors come from the theme ( for example with the CSS function light-dark() ).'=>'Styly, mezi kterými návštěvník přepíná. Styly pluginu nastavují jen CSS vlastnost color-scheme stránky, barvy dodává šablona (například CSS funkcí light-dark()).','The widget needs StyleSwitch to run by itself after it loads.'=>'Widget potřebuje, aby se StyleSwitch po načtení spustil sám.','The widget outputs the element <style-switch>, StyleSwitch fills it with the form control.'=>'Widget vypíše element <style-switch> a StyleSwitch do něj vloží ovládací prvek.','The widget writes the settings into the element with this id.'=>'Widget zapisuje nastavení do elementu s tímto id.','These settings of StyleSwitch are given by the plugin.'=>'Tato nastavení StyleSwitch určuje plugin.','Title:'=>'Název:','Tooltip of the switch'=>'Bublinová nápověda přepínače','Used only when there is no container, the widget always outputs one.'=>'Použije se jen bez kontejneru, widget ho vypisuje vždy.','Used when the widget has no title.'=>'Použije se, když widget nemá název.','Value'=>'Hodnota','When the operating system switches between light and dark colors'=>'Když operační systém přepne mezi světlými a tmavými barvami','When the site is embedded in another site, the choice is kept separately there.'=>'Když je web vložený do jiného webu, volba se tam ukládá zvlášť.','When you choose a color scheme of this site, your choice is saved in the cookie "%s" in your browser, so that the site is shown in the same color scheme on your next visit. The cookie contains only the addresses of the style sheets of this site and whether each of them is turned on. It is not used to identify or track you.'=>'Když si na tomto webu vyberete barevné schéma, vaše volba se uloží do cookie „%s“ ve vašem prohlížeči, aby se vám web při další návštěvě zobrazil ve stejném barevném schématu. Cookie obsahuje jen adresy stylů tohoto webu a údaj, zda je každý z nich zapnutý. Nepoužívá se k vaší identifikaci ani ke sledování.','Why'=>'Proč','Widgets'=>'Widgety','Without style (naked HTML)'=>'Bez stylu (čisté HTML)','assets/css/switch.css, it expects the default class names above. Turn it off when the theme styles the switch.'=>'assets/css/switch.css, počítá s výchozími názvy tříd výše. Vypněte, pokud přepínač styluje šablona.','https://iiic.dev/'=>'https://iiic.dev/','https://iiic.dev/style-switch'=>'https://iiic.dev/style-switch','ic'=>'ic','name of the first style'=>'název prvního stylu','name of the second style'=>'název druhého stylu','off'=>'vypnuto','on'=>'zapnuto','per widget'=>'podle widgetu']];
